/** Deterministic browser HTTP fixtures retain the real SDK's response and command validation. */
import {
  type AccessBrowserFrame,
  type AccessBrowserHandoff,
  browserActionSchema,
  browserResumeSchema,
  createAccessClient,
} from "access/client";

export const fixtureHandoff: AccessBrowserHandoff = {
  id: "f8dbca12-dc8e-41e5-83c1-c7136e2ef356",
  operationId: "174b4dda-e3ab-4b11-8266-5b17499a3184",
  expiresAt: 4102444800000,
  reason: "Complete the website verification to connect your account.",
  status: "waiting",
  capabilities: ["click", "scroll", "press", "resume"],
  unsupported: ["passkeys"],
};
export const fixtureFrame: AccessBrowserFrame = {
  handoffId: fixtureHandoff.id,
  version: 1,
  url: "https://example.com/verify",
  title: "Website verification",
  width: 800,
  height: 600,
  image: {
    mimeType: "image/png",
    base64:
      "",
  },
  expiresAt: fixtureHandoff.expiresAt,
};
interface BrowserCall {
  path: string;
  method: string;
  body: string | null;
  signal: AbortSignal | null;
}
export function createBrowserFixture(
  intercept?: (call: BrowserCall) => Promise<Response | null>,
) {
  const calls: BrowserCall[] = [];
  let frame = structuredClone(fixtureFrame);
  const client = createAccessClient({
    baseUrl: "https://access.example.test",
    token: () => "fixture-token",
    fetch: async (input, init) => {
      const call = {
        path: new URL(String(input)).pathname,
        method: init?.method ?? "GET",
        body: typeof init?.body === "string" ? init.body : null,
        signal: init?.signal ?? null,
      };
      calls.push(call);
      const response = await intercept?.(call);
      if (response) return response;
      if (call.path.endsWith("/frame") && call.method === "GET")
        return Response.json(frame);
      if (call.path.endsWith("/actions") && call.body) {
        const action = browserActionSchema.parse(JSON.parse(call.body));
        if (action.version !== frame.version)
          return Response.json({ error: "stale" }, { status: 409 });
        frame = { ...frame, version: frame.version + 1 };
        return Response.json(frame);
      }
      if (call.path.endsWith("/resume") && call.body) {
        const resume = browserResumeSchema.parse(JSON.parse(call.body));
        if (resume.version !== frame.version)
          return Response.json({ error: "stale" }, { status: 409 });
        return Response.json({
          id: resume.id,
          accountId: "example",
          kind: "resume",
          status: "pending",
          thread: "fixture-thread",
          createdAt: 0,
          updatedAt: 0,
          output: null,
          error: null,
        });
      }
      return Response.json(
        { error: "unsupported fixture route" },
        { status: 404 },
      );
    },
  });
  return { client, calls };
}
